/** The header's small "Colors" button: three sand dots of the current palette and the word. */
@Composable
fun PaletteButton(onClick: () -> Unit) {
    val palette = LocalPalette.current
    OutlinedButton(
        onClick = onClick,
        modifier = Modifier.height(32.dp),
        contentPadding = PaddingValues(horizontal = 10.dp),
        border = BorderStroke(1.dp, palette.glassOutline),
    ) {
        Canvas(Modifier.size(width = 22.dp, height = 10.dp)) {
            val dots = listOf(SandColor.RED, SandColor.YELLOW, SandColor.BLUE)
            val r = size.height / 2
            dots.forEachIndexed { i, color ->
                drawCircle(palette.sand(color), r, Offset(r + i * (size.width - 2 * r) / 2, r))
            }
        }
        Spacer(Modifier.width(6.dp))
        Text("Colors", fontSize = 13.sp)
    }
}

/**
 * A card at the bottom of the screen listing every palette as a small preview. Tapping one applies it at once
 * (the board above shows it); tapping outside or Done closes the card. Tapping Custom also opens its color
 * wheel ([CustomColorsEditor]) in the same card; [onCustom] gets each change, with `save` once a drag ends.
 */
@Composable
fun PalettePicker(
    current: Palette,
    custom: CustomScheme,
    onPick: (Palette) -> Unit,
    onCustom: (scheme: CustomScheme, save: Boolean) -> Unit,
    onDismiss: () -> Unit,
) {
    val palette = LocalPalette.current
    var editing by remember { mutableStateOf(false) }
    DismissOnBack(onBack = { if (editing) editing = false else onDismiss() })
    BoxWithConstraints(
        Modifier
            .fillMaxSize()
            .background(palette.scrim.copy(alpha = palette.scrim.alpha * (if (editing) 0.3f else 0.6f)))
            .clickable(interactionSource = remember { MutableInteractionSource() }, indication = null, onClick = onDismiss),
        contentAlignment = Alignment.BottomCenter,
    ) {
        val compact = editing && maxHeight < 560.dp && maxWidth >= 480.dp
        Surface(
            Modifier.widthIn(max = if (compact) 600.dp else 420.dp).fillMaxWidth().padding(12.dp),
            shape = RoundedCornerShape(20.dp),
            tonalElevation = 8.dp,
            shadowElevation = 8.dp,
        ) {
            // Scrolls when the screen is short (landscape phones, small desktop windows).
            Column(
                Modifier.verticalScroll(rememberScrollState()).padding(16.dp),
                verticalArrangement = Arrangement.spacedBy(10.dp),
            ) {
                if (editing) {
                    CustomColorsEditor(
                        custom,
                        compact = compact,
                        onChange = onCustom,
                        onBack = { editing = false },
                        onDone = onDismiss,
                    )
                } else {
                    Text("Colors", fontSize = 20.sp, fontWeight = FontWeight.Bold, color = palette.accent)
                    for (option in Palettes.all) {
                        PaletteOption(option, isCurrent = option.name == current.name, onClick = { onPick(option) })
                    }
                    val customPalette = remember(custom) { custom.palette() }
                    PaletteOption(
                        customPalette,
                        isCurrent = current.name == CustomScheme.NAME,
                        note = "Edit \u203A",
                        onClick = { onPick(customPalette); editing = true },
                    )
                    Button(onClick = onDismiss, modifier = Modifier.align(Alignment.End)) { Text("Done") }
                }
            }
        }
    }
}

/** One palette drawn in its own colors: its background, its name in its accent, and a swatch of every sand. */
@Composable
private fun PaletteOption(option: Palette, isCurrent: Boolean, onClick: () -> Unit, note: String? = null) {
    val marker = LocalPalette.current.highlight
    val shape = RoundedCornerShape(14.dp)
    Surface(
        onClick = onClick,
        modifier = Modifier.fillMaxWidth().semantics { selected = isCurrent },
        shape = shape,
        color = option.backgroundTop,
        border = if (isCurrent) BorderStroke(3.dp, marker) else BorderStroke(1.dp, option.glassOutline),
    ) {
        Column(
            Modifier
                .background(Brush.verticalGradient(listOf(option.backgroundTop, option.backgroundBottom)))
                .padding(horizontal = 12.dp, vertical = 10.dp),
        ) {
            Row(verticalAlignment = Alignment.CenterVertically) {
                Text(option.name, color = option.accent, fontSize = 16.sp, fontWeight = FontWeight.Bold)
                Spacer(Modifier.weight(1f))
                val label = listOfNotNull(if (isCurrent) "In use" else null, note).joinToString("  \u00B7  ")
                if (label.isNotEmpty()) Text(label, color = option.dimText, fontSize = 12.sp)
            }
            Spacer(Modifier.height(8.dp))
            Canvas(Modifier.fillMaxWidth().height(18.dp)) {
                val colors = SandColor.entries
                val gap = 4.dp.toPx()
                val w = (size.width - gap * (colors.size - 1)) / colors.size
                colors.forEachIndexed { i, color ->
                    drawRoundRect(
                        option.sand(color),
                        topLeft = Offset(i * (w + gap), 0f),
                        size = Size(w, size.height),
                        cornerRadius = CornerRadius(4.dp.toPx()),
                    )
                }
            }
        }
    }
}
